  private restore(){try{const raw=localStorage.getItem(this.storageKey());if(raw&&raw.length<65536){const p=JSON.parse(raw);if(p.topic_id===this.topic&&typeof p.key==='string'&&(p.job_id===null||typeof p.job_id==='string')&&p.input&&p.input.topic_id===this.topic)this.pending=p;}}catch{/* 损坏定位不能当作没有任务。 */}}
