  private async cancelLateAccepted(id:string,pending:Pending,c:FeatureContext){
    try{const detail=await c.client.request<JobDetailResponse>('GET','/api/v1/jobs/'+path(id),undefined,{signal:c.signal});
      if(detail.job.id===id&&detail.job.target_id===pending.topic_id&&detail.job.input_hash===pending.input_hash&&activeStates.includes(detail.job.state))
        await c.client.cancelJob(id,detail.job.version,{signal:c.signal,idempotencyKey:crypto.randomUUID()});
    }catch{/* 已知原任务定位保留；本机停止不能证明远端取消，也不能再次提交。 */}
  }
